package com.yonlab.offlinevoice;
/** Local pure report template; no dependency on vision or network. */
final class VoiceReportHtml {
 private VoiceReportHtml(){}
 private static String escape(String value){return VoiceReportText.html(value);}
 public static StringBuilder start(String title,String subtitle,String logo){
  StringBuilder b=new StringBuilder("<!doctype html><html lang='ko'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; img-src data:; style-src 'unsafe-inline'; connect-src 'none'; base-uri 'none'; form-action 'none'\"><title>");
  b.append(escape(title)).append("</title><style>").append(style()).append("</style><header class='brand'>");
  b.append("<strong>AXSL Vision</strong>");
  return b.append("<span>AI 결과 리포트</span></header><main><div class='eyebrow'>AXSL Vision</div><h1>").append(escape(title)).append("</h1><p class='lead'>").append(escape(subtitle)).append("</p>");
 }
 public static boolean image(String value,String format){return value!=null&&value.matches("data:image/"+format+";base64,[A-Za-z0-9+/=]+");}
 public static String style(){return
  "*{box-sizing:border-box}body{margin:0;background:#f7faff;color:#071b45;font:16px/1.6 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:40px 24px 64px}.brand{background:white;border-bottom:1px solid #d8e4f5;padding:20px 24px;display:flex;align-items:center;justify-content:space-between}.brand>*+*{margin-left:24px}.brand .logo{width:168px;height:auto}.brand span,.muted,small{color:#4b5e83}.eyebrow{font-size:13px;color:#0068f8;letter-spacing:.08em;font-weight:700}h1{font-size:32px;font-size:clamp(26px,4vw,38px);line-height:1.2;margin:8px 0 12px}h2{font-size:21px;line-height:1.4;margin:0 0 12px}h3{font-size:16px;margin:0 0 8px}.lead{color:#4b5e83;margin-bottom:28px}"
  +".overview{display:flex;flex-wrap:wrap;margin:16px -8px 24px}.overview>.stat{flex:1 1 160px;min-width:0;margin:8px}.stat{padding:20px;background:white;border:1px solid #d8e4f5;border-radius:12px}.stat strong{font-size:25px;display:block;color:#001850}.report-grid{display:block}.result-card{min-width:0;background:white;border:1px solid #d8e4f5;border-radius:12px;padding:24px;margin-bottom:24px}.card-top{display:flex;align-items:flex-start;justify-content:space-between}.card-top>*+*{margin-left:12px}.card-top h2{min-width:0}.badge{display:inline-block;flex-shrink:0;white-space:nowrap;border-radius:20px;background:#eaf2ff;color:#0068f8;padding:4px 10px;font-size:12px;font-weight:700}.badge.error{background:#fff0ee;color:#d92d20}.badge.done{background:#e8f7f1;color:#0f9f6e}.summary{font-size:18px;line-height:1.55;margin:16px 0;white-space:pre-wrap;overflow-wrap:anywhere}.model-media,.model-detail{min-width:0}.result-image{width:100%;height:auto;max-height:380px;object-fit:contain;background:#f7faff;border:1px solid #d8e4f5;border-radius:12px;margin:8px 0 16px}"
  +".timings{display:flex;margin:12px -4px}.timings>div{flex:1 1 0;background:#f7faff;border-radius:8px;padding:10px 8px;min-width:0;margin:4px}.timings strong{display:block;font-size:17px}.timings span{font-size:12px;color:#4b5e83}progress{width:100%;height:8px;accent-color:#0068f8}dl{display:grid;grid-template-columns:minmax(85px,1fr) minmax(0,2fr);grid-gap:8px 12px;gap:8px 12px;margin:16px 0}dt{color:#4b5e83}dd{margin:0;overflow-wrap:anywhere}details{margin-top:20px;padding-top:16px;border-top:1px solid #d8e4f5}summary{cursor:pointer;color:#0068f8;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.6 system-ui,sans-serif;color:#4b5e83}code,small{overflow-wrap:anywhere}.table{overflow:auto;background:white;border:1px solid #d8e4f5;border-radius:12px;margin-top:16px}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;padding:14px;border-bottom:1px solid #d8e4f5;white-space:pre-wrap;overflow-wrap:anywhere}th{background:#001850;color:white}footer{margin-top:32px;color:#4b5e83;font-size:13px}"
  +"@supports(display:grid){.overview{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));grid-gap:16px;gap:16px;margin:24px 0 32px}.overview>.stat{margin:0}.report-grid{display:grid;grid-template-columns:1fr;grid-gap:24px;gap:24px;align-items:start}.report-grid>.result-card{margin-bottom:0}.report-grid>.result-card:only-child{grid-column:1/-1}.timings{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-gap:8px;gap:8px;margin:16px 0}.timings>div{margin:0}}"
  +"@media(min-width:720px){.report-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.report-grid.single{grid-template-columns:1fr}.model-body.with-image{display:flex;align-items:flex-start}.model-body.with-image>.model-media{flex:1 1 0}.model-body.with-image>.model-detail{flex:1 1 0;margin-left:24px}.model-body.with-image .timings{margin-top:8px}}@media(min-width:1160px){.report-grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}}"
  +"@media(max-width:480px){main{padding:24px 16px 40px}.result-card{padding:20px}.brand{padding:16px}.brand span{display:none}.overview{grid-gap:12px;gap:12px}.timings{display:block;margin:16px 0}.timings>div{margin:8px 0}.timings strong{display:inline;margin-right:8px}}@media print{body{background:white}details{break-inside:avoid}.result-card{break-inside:avoid}.report-grid{display:block}.result-card{margin-bottom:20px}}";
 }
}
